function buildSitecraftBackground(p){
 const isColor=v=>/^#[0-9a-f]{3,8}$/i.test(String(v||''));
 const safe=(v,f)=>isColor(v)?v:f;
 const clamp=(v,min,max,d)=>Number.isFinite(Number(v))?Math.min(max,Math.max(min,Number(v))):d;
 const types='solid gradient radial mesh animated-gradient rainbow pulse breathing aurora orbs lava spotlight shimmer sunset neon-grid stars galaxy bubbles confetti grid dots stripes checker vortex ripples fog ocean meteor spot-dance'.split(' ');
 const fx=types.includes(p.bgEffect)?p.bgEffect:'solid';
 const el=document.createElement('div');el.className='sc-background';el.dataset.effect=fx;el.setAttribute('aria-hidden','true');
 if(p.bgMotion===false)el.classList.add('sc-bg-still');
 el.style.setProperty('--sc-c1',safe(p.bgColor1,safe(p.bg,'#ffffff')));
 el.style.setProperty('--sc-c2',safe(p.bgColor2,'#7c3aed'));
 el.style.setProperty('--sc-c3',safe(p.bgColor3,'#22d3ee'));
 el.style.setProperty('--sc-angle',clamp(p.bgAngle,0,360,135)+'deg');
 el.style.setProperty('--sc-duration',clamp(p.bgSpeed,3,90,16)+'s');
 el.style.setProperty('--sc-intensity',String(clamp(p.bgIntensity,0,100,72)/100));
 el.style.setProperty('--sc-size',String(clamp(p.bgScale,35,250,100)/100));
 for(let i=1;i<=3;i++){const shape=document.createElement('span');shape.className='sc-bg-shape s'+i;el.append(shape)}
 return el;
}

