function blankPage(name='Home',slug='home'){return {id:uid(),name,slug,height:1500,bg:'#ffffff',bgEffect:'solid',bgSpeed:16,bgIntensity:72,bgScale:100,bgAngle:135,bgMotion:true,elements:[]}}
