let project;try{const val=localStorage.getItem(STORAGE_KEY);project=val?JSON.parse(val):blankProject();if(!validProject(project))project=blankProject()}catch{project=blankProject()}
let activeTab='add',selected=null,zoom=.75,showGrid=true,hist=[],future=[],saveTimer=null,toastTimer=null,dragState=null,previewDevice='desktop';
function validProject(p){return p&&p.version===2&&Array.isArray(p.pages)&&p.pages.length>0&&p.pages.length<100&&p.pages.every(g=>g&&Array.isArray(g.elements)&&typeof g.slug==='string')}
function page(){return project.pages.find(p=>p.id===project.selectedPage)||project.pages[0]}
function element(){return selected?page().elements.find(e=>e.id===selected):null}
function checkpoint(){hist.push(JSON.stringify(project));if(hist.length>75)hist.shift();future=[];updateUndo()}
function updateUndo(){$('undoBtn').disabled=!hist.length;$('redoBtn').disabled=!future.length}
function persist(){clearTimeout(saveTimer);if(cloudToken){cloudStatus('Saving to cloud…');return;}cloudStatus('Saving guest draft…');saveTimer=setTimeout(()=>{try{localStorage.setItem(STORAGE_KEY,JSON.stringify(project));cloudStatus('Guest draft saved on this device','ok')}catch{cloudStatus('Local draft unavailable','error')}},350)}
function commit(renderAll=true){persist();markCloudDirty();if(renderAll)render();else renderSidebar();}
function toast(text){const x=$('toast');x.textContent=text;x.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>x.classList.remove('show'),2800)}
