if(name==='gallery')x=`<div class="widget-gallery">${ls.length?ls.slice(0,6).map((u,i)=>validImg(u)?`<img src="${esc(u)}" alt="Gallery photo ${i+1}">`:`<div class="widget-placeholder">Image ${i+1}</div>`).join(''):'<div class="widget-placeholder">▧ &nbsp; Add photos in Settings →</div>'}</div>`;
if(name==='orderform'||name==='paybutton')x=name==='paybutton'?`<div class="site-button" style="display:grid;place-items:center;width:100%;height:100%;font-weight:700">${esc(e.text||'Pay securely')} · ${esc(e.currency||'gbp')} ${esc(e.price||0)}</div>`:`<div class="widget-form">${rows(e.items).map(r=>`<label>${esc(r[0]||'Field')}<div>Enter ${esc(r[0]||'value')}…</div></label>`).join('')}<span class="fake-submit">${esc(e.text||'Send enquiry')}</span></div>`;
