if(name==='beforeafter')x=`<div class="sc-compare">${ls.length>=2&&ls.every(validImg)?`<img src="${esc(ls[0])}" alt="Before"><img class="sc-after" src="${esc(ls[1])}" alt="After">`:'<div class="sc-media-empty">Upload two photos to compare</div>'}<span class="sc-compare-left">${esc(e.beforeLabel||'Before')}</span><span class="sc-compare-right">${esc(e.afterLabel||'After')}</span><span class="sc-compare-line"></span></div>`;
