function tickCountdown(){document.querySelectorAll('[data-countdown]').forEach(el=>{const d=new Date(el.dataset.countdown),diff=Math.max(0,d-Date.now());if(!Number.isFinite(diff)){el.textContent='Set a valid countdown date';return}const days=Math.floor(diff/864e5),hr=Math.floor(diff/36e5)%24,min=Math.floor(diff/6e4)%60,sec=Math.floor(diff/1000)%60;el.textContent=[days,hr,min,sec].map(n=>String(n).padStart(2,'0')).join(' : ')})}
