// Website element clipboard: stays in memory, never leaks cloud data into guest drafts.
const SC_ELEMENT_CLIP_PREFIX='SITECRAFT_ELEMENT_V1\n';
let scElementClipboard=null,scClipboardPage=null,scClipboardOffset=0;
function scClipboardRefresh(){const copy=$('quickCopy'),paste=$('quickPaste');if(copy)copy.disabled=!element();if(paste)paste.disabled=!scElementClipboard||isGame();}
function scClipboardCopy(){
  if(isGame()){toast('Select a website element to copy. Game objects have a separate Duplicate action.');return;}
  const source=element();if(!source){toast('Select a button, text box, picture or other element first.');return;}
  scElementClipboard=deep(source);scClipboardPage=page().id;scClipboardOffset=0;
  const payload=SC_ELEMENT_CLIP_PREFIX+JSON.stringify(scElementClipboard);
  // Best effort: native clipboard supports pasting in a second Sitecraft tab.
  // A browser may deny clipboard access; internal Copy / Paste continues working.
  try{if(navigator.clipboard?.writeText)navigator.clipboard.writeText(payload).catch(()=>{});}catch{}
  scClipboardRefresh();toast('Copied '+(BLOCKS.find(x=>x[0]===source.type)?.[1]||source.type)+'. Paste on this or another page.');
}
function scClipboardPaste(clipData=null){
  if(isGame())return;
  let data=scElementClipboard;
  if(typeof clipData==='string'&&clipData.startsWith(SC_ELEMENT_CLIP_PREFIX)){
    try{const parsed=JSON.parse(clipData.slice(SC_ELEMENT_CLIP_PREFIX.length));if(parsed&&typeof parsed==='object'&&BLOCKS.some(b=>b[0]===parsed.type)&&Array.isArray(project.pages)){data=parsed}}catch{}
  }
  if(!data){toast('Copy an element first, then select the page to paste it on.');return;}
  if(!BLOCKS.some(b=>b[0]===data.type))return;
  checkpoint();const pasted=deep(data);pasted.id=uid();const p=page();
  scClipboardOffset+=24;
  const otherPage=scClipboardPage!==p.id;
  const visibleTop=($('workspace').scrollTop||0)/zoom;
  const dx=otherPage?0:scClipboardOffset,dy=otherPage?Math.max(0,visibleTop+45-data.y):scClipboardOffset;
  pasted.x=clamp((Number(data.x)||0)+dx,0,Math.max(0,PAGE_WIDTH-(Number(pasted.w)||100)));
  pasted.y=clamp((Number(data.y)||0)+dy,0,19000);
  // A pasted element must have a unique identity, but should preserve text, images,
  // appearance, links, buttons and all custom settings.
  p.elements.push(pasted);p.height=Math.min(20000,Math.max(p.height,pasted.y+(Number(pasted.h)||80)+140));
  selected=pasted.id;commit();scClipboardRefresh();toast('Pasted! Drag to move it or use the settings panel to edit.');
}
async function scClipboardPasteButton(){
  // Buttons normally use the in-memory copy, with OS clipboard as a fallback.
  if(scElementClipboard){scClipboardPaste();return;}
  try{const content=await navigator.clipboard?.readText?.();scClipboardPaste(content)}catch{scClipboardPaste()}
}
