function deleteElement(){if(!element())return;checkpoint();page().elements=page().elements.filter(e=>e.id!==selected);selected=null;commit();scClipboardRefresh()}
function layerMove(d){const e=element();if(!e)return;const arr=page().elements,i=arr.indexOf(e),j=d>0?arr.length-1:0;if(i===j)return;checkpoint();arr.splice(i,1);arr.splice(j,0,e);commit()}
function handleAction(action){switch(action){case'new-guest-project':if(cloudToken){cloudShowLibrary();break;}if(!confirm('Start a blank website? Download an editable backup first if you want to keep this guest draft.'))break;project=blankProject();selected=null;hist=[];future=[];activeTab='add';commit();toast('New blank website ready.');break;case'new-page':addPage();break;case'go-add':activeTab='add';renderSidebar();break;case'backup':backup();break;case'import':$('importInput').click();break;case'duplicate-page':addPage(true);break;case'delete-page':removePage(page().id);break;case'copy-element':scClipboardCopy();break;case'paste-element':scClipboardPasteButton();break;case'duplicate-element':copyElement();break;case'delete-element':deleteElement();break;case'front':layerMove(1);break;case'back':layerMove(-1);break}}
