function imageUpload(file){if(!file)return;if(!file.type.startsWith('image/')){toast('Choose an image file.');return}if(file.size>20e6){toast('Please choose an image smaller than 20 MB.');return}const reader=new FileReader();reader.onload=()=>{const e=element();if(!e||!['image','product'].includes(e.type))return;const img=new Image();img.onload=()=>{const max=1600,ratio=Math.min(1,max/Math.max(img.width,img.height)),canvas=document.createElement('canvas');canvas.width=Math.round(img.width*ratio);canvas.height=Math.round(img.height*ratio);const ctx=canvas.getContext('2d');ctx.drawImage(img,0,0,canvas.width,canvas.height);const src=canvas.toDataURL(file.type==='image/png'?'image/png':'image/jpeg',.83);checkpoint();e.src=src;e.alt=e.alt==='Your image'?file.name:e.alt;commit();toast('Image uploaded and embedded in your website.')};img.onerror=()=>toast('That image could not be opened.');img.src=reader.result};reader.readAsDataURL(file)}

async function galleryUpload(files){const e=element();if(!e||!['gallery','carousel','beforeafter'].includes(e.type)||!files?.length)return;const results=[];for(const file of Array.from(files).slice(0,15)){if(!file.type.startsWith('image/'))continue;const src=await new Promise((res,reject)=>{const fr=new FileReader();fr.onload=()=>{const im=new Image();im.onload=()=>{const c=document.createElement('canvas'),scale=Math.min(1,1200/Math.max(im.width,im.height));c.width=Math.max(1,Math.round(im.width*scale));c.height=Math.max(1,Math.round(im.height*scale));c.getContext('2d').drawImage(im,0,0,c.width,c.height);res(c.toDataURL('image/jpeg',.77))};im.onerror=reject;im.src=fr.result};fr.onerror=reject;fr.readAsDataURL(file)}).catch(()=>null);if(src)results.push(src)}if(!results.length){toast('No usable photos were selected.');return}checkpoint();e.items=[e.items,...results].filter(Boolean).join('\n');commit();toast(results.length+' gallery photos added.')}

function initProjectIcon(){const chooser=$('projectIconFile');const pick=()=>chooser.click();$('projectIconBtn').addEventListener('click',pick);$('gameIconBtn').addEventListener('click',pick);chooser.addEventListener('change',async()=>{const file=chooser.files?.[0];chooser.value='';if(!file)return;if(!/^image\/(png|jpe?g|webp|gif)$/.test(file.type)||file.size>6*1024*1024){alert('Choose a PNG, JPEG, WebP or GIF under 6 MB.');return}try{const image=new Image(),url=URL.createObjectURL(file);await new Promise((resolve,reject)=>{image.onload=resolve;image.onerror=reject;image.src=url});const canvas=document.createElement('canvas');canvas.width=96;canvas.height=96;const ctx=canvas.getContext('2d');ctx.clearRect(0,0,96,96);const scale=Math.min(96/image.width,96/image.height),w=image.width*scale,h=image.height*scale;ctx.drawImage(image,(96-w)/2,(96-h)/2,w,h);URL.revokeObjectURL(url);checkpoint();project.icon=canvas.toDataURL('image/png');commit();toast('Browser-tab icon saved. It will appear in your exported website or game.')}catch(e){alert('Could not process this image. Please try another PNG or JPEG.')}})}
