function renderHotbar(){const bar=$('g-hotbar');if(!bar)return;bar.replaceChildren();const list=itemDefs.filter(d=>num(bag[d.id])>0).slice(0,5);for(let i=0;i<5;i++){const d=list[i],b=document.createElement('button');b.type='button';b.setAttribute('aria-label',d?cleanText(d.name)+' quick slot '+(i+1):'Empty quick slot '+(i+1));b.title=d?cleanText(d.name)+' — press '+(i+1):'Empty';if(d){b.textContent=d.icon||'📦';b.classList.toggle('equipped',equippedItemId===d.id);const count=document.createElement('small');count.textContent=String(Math.floor(num(bag[d.id])));b.append(count);b.onclick=()=>useBagItem(d.id)}else b.disabled=true;const label=document.createElement('em');label.textContent=i+1;b.append(label);bar.append(b)}}
function addToBag(id,quantity=1){const def=itemFor(id);if(!def){say('This pickup has no valid item configured');return false}bag[id]=Math.min(9999,Math.max(0,num(bag[id]))+clamp(Math.floor(quantity),1,100));renderHotbar();say((def.icon||'🎒')+' +'+quantity+' '+cleanText(def.name));sound(820,.12);return true}
function useBagItem(id){const def=itemFor(id),quantity=num(bag[id]);if(!def||quantity<=0)return;
 if(def.category==='weapon'){equippedItemId=(equippedItemId===id?null:id);say(equippedItemId?'Equipped '+cleanText(def.name):'Unequipped '+cleanText(def.name));}
 else if(def.category==='consumable'){const power=clamp(num(def.power,20),0,500);health=Math.min(maxHealth,health+power);bag[id]--;say((def.icon||'🍎')+' '+cleanText(def.name)+' used · +'+power+' health');stats();}
 else {say(cleanText(def.name)+' is stored in your bag. It can be collected and kept for your world.');}
 renderHotbar();if(!$('g-panel').hidden&&$('g-panel').dataset.mode==='inventory')renderBag();}
function renderBag(){const box=$('g-panel-content');box.replaceChildren();const summary=document.createElement('p');summary.textContent='🪙 '+coinsCount+' coins  ·  💎 '+gemsCount+' gems  ·  🗝 '+keysCount+' keys';box.append(summary);let count=0;for(const def of itemDefs){const qty=Math.floor(num(bag[def.id]));if(qty<1)continue;count++;const b=document.createElement('button');b.className='g-menu-btn';b.textContent=(def.icon||'📦')+' '+cleanText(def.name)+' ×'+qty+(def.category==='weapon'?(equippedItemId===def.id?'  ✓ Equipped':'  · Equip'):def.category==='consumable'?'  · Use':'  · Stored');b.onclick=()=>useBagItem(def.id);box.append(b);if(def.description){const p=document.createElement('div');p.style.cssText='font-size:11px;color:#adbed7;margin:-7px 0 8px 6px';p.textContent=cleanText(def.description);box.append(p)}}if(!count){const p=document.createElement('p');p.textContent='Your bag is empty. Pick up items or open chests to collect things.';box.append(p)}}

function act(action,value){if(editMode)return;switch(action){case'jump':if(grounded){velY=clamp(num(S.jump,9)+jumpBonus,3,25);grounded=false;jumps++;progress('jumps',1);sound(350)}break;case'sprint':keys.add('ShiftLeft');setTimeout(()=>keys.delete('ShiftLeft'),1200);break;case'attack':attack();break;case'interact':interact();break;case'quests':toggleModal('quests');break;case'inventory':toggleModal('inventory');break;case'shop':toggleModal('shop');break;case'restart':restart();break;case'heal':if(coinsCount>=10){coinsCount-=10;health=Math.min(maxHealth,health+40);stats();say('Healed for 10 coins')}else say('Need 10 coins');break;case'checkpoint':respawn();break;case'message':say(value||'Hello from Sitecraft!');break;case'map':mapVisible=!mapVisible;$('g-minimap').hidden=!mapVisible;break;case'save':saveGame();break;case'load':loadGame();break;case'help':toggleModal('help');break;case'dash':{const dx=-Math.sin(yaw)*6,dz=-Math.cos(yaw)*6;slideMove(dx,dz);say('💨 Dash!');break;}case'emote':say('🎉 Victory dance!');sound(980,.2);break;case'link':{let url=String(value||'');if(/^https?:\/\//i.test(url))window.open(url,'_blank','noopener,noreferrer');else say('This button needs a valid HTTPS URL');break;}default:toggleModal('help')}}
function restart(){for(const c of [...coins,...gems,...keysPickups,...xpPickups]){c.hit=false;c.g.visible=true}for(const e of enemies){e.dead=false;e.hp=Math.max(1,num(e.d.enemyHealth,40));e.g.visible=true;e.g.position.copy(e.origin)}for(const h of heals){h.used=false;h.g.visible=true}for(const c of checkpoints)c.used=false;for(const key of Object.keys(bag))delete bag[key];for(const d of itemDefs)if(d.starter)bag[d.id]=1;equippedItemId=null;for(const c of interactables){if(c.kind==='itemPickup'){c.used=false;c.g.visible=true;c.lastOpen=-100}else if(c.kind==='chest'){c.used=false;c.lidTarget=0;c.lastOpen=-100}else if(c.kind==='door'){c.unlocked=false;setDoorState(c,false)}else if(c.kind==='switch'){c.on=false;c.at=-100}else if(c.kind==='rest')c.at=-100}for(const l of lights)setLight(l,true);activeSpawn={x:num(spawn.x),y:num(spawn.y),z:num(spawn.z)};coinsCount=0;gemsCount=0;keysCount=0;kills=0;jumps=0;distance=0;lastDistanceMilestone=0;speedBonus=0;jumpBonus=0;xp=0;level=1;maxHealth=clamp(num(S.maxHealth,100),20,500);health=maxHealth;elapsed=0;finished=false;Object.values(qProgress).forEach(q=>{q.value=0;q.done=false});$('g-win').hidden=true;$('g-panel').hidden=true;respawn(true);say('New run! Complete the challenges.');stats()}
