function handleKey(ev,down){if(editMode)return;const tag=document.activeElement?.tagName;if(['INPUT','TEXTAREA'].includes(tag))return;const code=ev.code;if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(code))ev.preventDefault();if(down&&ev.repeat)return;if(down){keys.add(code);if(code==='Space')act('jump');if(code==='KeyE')act('interact');if(code==='KeyF')act('attack');if(code==='KeyQ')act('quests');if(code==='KeyM')act('map');if(code==='KeyX'&&S.enableDash!==false)act('dash');if(code==='KeyP')saveGame();if(code==='KeyI')act('inventory');if(code.startsWith('Digit')&&Number(code.slice(5))>=1&&Number(code.slice(5))<=5){const items=itemDefs.filter(d=>num(bag[d.id])>0);const d=items[Number(code.slice(5))-1];if(d)useBagItem(d.id)}if(code==='KeyR')act('restart');if(code==='Escape')$('g-panel').hidden=true;}else keys.delete(code)}
