function isGame(){return !!(project&&project.kind==='game3d'&&project.game&&project.game.settings&&Array.isArray(project.game.objects))}
function gameTerrainEnsure(){const g=project.game;if(!g)return;const len=TERRAIN_RES*TERRAIN_RES;if(!g.terrain||g.terrain.res!==TERRAIN_RES||!Array.isArray(g.terrain.heights)||g.terrain.heights.length!==len){g.terrain={res:TERRAIN_RES,heights:Array(len).fill(0),paints:Array(len).fill(0),waterEnabled:true,waterLevel:-2}}if(!Array.isArray(g.terrain.paints)||g.terrain.paints.length!==len)g.terrain.paints=Array(len).fill(0);if(g.terrain.waterLevel===undefined)g.terrain.waterLevel=-2;if(g.terrain.waterEnabled===undefined)g.terrain.waterEnabled=true;return g.terrain}
function gameTerrainPreset(preset){if(!isGame())return;if(!['clearPaint','flat'].includes(preset)&&!confirm('Replace the current sculpted terrain with '+preset+'? You can undo this change.'))return;checkpoint();const t=gameTerrainEnsure(),N=TERRAIN_RES;for(let z=0;z<N;z++)for(let x=0;x<N;x++){const idx=z*N+x,u=x/(N-1)*2-1,v=z/(N-1)*2-1,r=Math.hypot(u,v),sin=(n)=>Math.sin(n),noise=sin(x*.41+z*.17)*sin(z*.34-x*.16)+.34*sin(x*.13+z*.29);let h=0,paint=0;if(preset==='hills'){h=1.1+2.3*(sin(x*.14+z*.065)+sin(z*.20-x*.095)+noise*.4);paint=h>6?2:0}else if(preset==='mountains'){h=2+Math.max(0,1-r*.9)*((sin(x*.16)+sin(z*.135)+2)*5+Math.abs(noise)*3);paint=h>18?3:h>9?2:0}else if(preset==='valley'){h=8*Math.min(1,Math.pow(Math.abs(u*.8+sin(v*5)*.09),1.25)*2)+noise*.3;paint=Math.abs(u)<.22?1:0}else if(preset==='island'){h=-4+Math.max(0,1-r*.91)*19+noise*.55;paint=h<1?1:0}else if(preset==='clearPaint'){t.paints[idx]=0;continue}t.heights[idx]=Math.round(Math.max(-25,Math.min(45,h))*10)/10;if(preset!=='flat')t.paints[idx]=paint;else t.paints[idx]=0}if(preset==='island'||preset==='valley')t.waterLevel=0;else if(preset==='flat')t.waterLevel=-2;gameChanged();toast('Terrain updated — use the sculpt brushes to refine it.');}
function terrainSendTool(){const f=$('gameFrame');if(!f||!f.contentWindow)return;f.contentWindow.postMessage({sitecraftTerrain:true,type:'tool',tool:gameSection==='terrain'?terrainTool:'none',radius:terrainRadius,strength:terrainStrength,flatten:terrainFlatten,paint:terrainPaint},'*');studioSendView()}
function defaultGameItems(){return [{id:'starter_sword',name:'Training sword',icon:'⚔️',category:'weapon',description:'A reliable starter sword.',power:25,range:3.4,stack:1,starter:true},{id:'healing_apple',name:'Healing apple',icon:'🍎',category:'consumable',description:'Restores 30 health.',power:30,stack:12,starter:false},{id:'wood',name:'Wood',icon:'🪵',category:'resource',description:'Useful for crafting.',power:0,stack:99,starter:false},{id:'stone',name:'Stone',icon:'🪨',category:'resource',description:'Useful for building.',power:0,stack:99,starter:false},{id:'bow',name:'Training bow',icon:'🏹',category:'weapon',description:'A ranged weapon.',power:20,range:12,stack:1,starter:false}]}
function gameEnsure(){if(!isGame())return;gameTerrainEnsure();const g=project.game;g.prefabs=Array.isArray(g.prefabs)?g.prefabs:[];g.quests=Array.isArray(g.quests)?g.quests:[];g.ui=Array.isArray(g.ui)?g.ui:[];g.items=Array.isArray(g.items)?g.items:defaultGameItems();g.shop=Array.isArray(g.shop)?g.shop:[{id:uid(),name:'Health potion',effect:'heal',amount:50,cost:10}];g.settings={maxHealth:100,ambient:1.65,fog:0,sound:true,showHUD:true,coinsForWin:0,winMessage:'Level completed!',timeOfDay:'day',weather:'clear',weatherIntensity:35,dayCycle:false,dayCycleSpeed:100,showMiniMap:true,showStamina:true,enableDash:true,saveProgress:true,gameIntro:true,gameSubtitle:'Explore, complete quests and discover the world!',...g.settings};}
function gameSelectedObject(){return isGame()?project.game.objects.find(o=>o.id===gameSelected):null}
function gameGetField(k,value,kind='number'){if(kind==='checkbox')return `<label class="sg-check"><input type="checkbox" data-g-setting="${k}" ${value?'checked':''}> ${k.replace(/([A-Z])/g,' $1')}</label>`;if(kind==='textarea')return `<label>${k.replace(/([A-Z])/g,' $1')}<textarea data-g-setting="${k}" rows="3">${esc(String(value??''))}</textarea></label>`;return `<label>${k.replace(/([A-Z])/g,' $1')}<input type="${kind}" data-g-setting="${k}" value="${esc(String(value??''))}" ${kind==='number'?'step="0.5"':''}></label>`}
function gameStylePanel(){if(!isGame())return;gameEnsure();const g=project.game,P=$('gameProps');
 if(gameSection==='explorer'){/* Use the same object inspector as World. */}if(gameSection==='models'){P.innerHTML='<div class="sg-subtitle">REUSABLE MODELS</div><h3>Build once. Reuse often.</h3><p>Save a set of objects as a model, then place new editable instances with one click.</p>';return}if(gameSection==='check'){P.innerHTML='<div class="sg-subtitle">BUILD VALIDATION</div><h3>Make games that work</h3><p>Check your scene before exporting to avoid missing spawns, broken links and parts outside the map.</p>';return}if(gameSection==='terrain'){const t=gameTerrainEnsure();P.innerHTML=`<div class="sg-subtitle">LANDSCAPE BRUSH</div><h3>⛰ Sculpt & paint terrain</h3><p>Choose a brush on the left, then drag over the ground. Right-drag to rotate, or choose Move camera to drag on touchscreens.</p><div class="sg-card">Active: <b id="terrainToolName">${esc(({raise:'⛰ Raise',lower:'⬇ Lower',smooth:'〰 Smooth',flatten:'▰ Flatten',paint:'🎨 Paint',water:'💧 Water',sample:'⌖ Pick height',none:'👆 Camera'})[terrainTool])}</b></div><label>Brush size <b id="terrainRadiusValue">${terrainRadius}</b> metres<input class="sg-terrain-slider" data-terrain-input="radius" type="range" min="2" max="200" step="1" value="${terrainRadius}"></label><label>Brush strength <b id="terrainStrengthValue">${terrainStrength}</b><input class="sg-terrain-slider" data-terrain-input="strength" type="range" min="0.2" max="8" step="0.2" value="${terrainStrength}"></label><label>Flatten to this elevation <input data-terrain-input="flatten" type="number" min="-25" max="45" step="0.5" value="${terrainFlatten}"></label><div class="sg-terrain-sub">PAINT MATERIAL</div><div class="sg-terrain-swatch">${TERRAIN_COLORS.map((c,i)=>`<button type="button" data-terrain-paint="${i}" style="background:${c}" class="${terrainPaint===i?'active':''}" title="${['Grass','Sand','Rock','Snow','Dirt','Forest'][i]}"></button>`).join('')}</div><p class="sg-help">Grass · Sand · Rock · Snow · Dirt · Forest. Select Paint to apply the chosen material.</p><div class="sg-terrain-sub">WATER & LAKES</div><label class="sg-check"><input type="checkbox" data-terrain-property="waterEnabled" ${t.waterEnabled?'checked':''}> Show water in carved-out areas</label><label>Water surface elevation<input type="number" data-terrain-property="waterLevel" min="-24" max="35" step="0.5" value="${t.waterLevel}"></label><div class="sg-terrain-help">💡 To make a lake, use <b>Carve water</b> then set the water elevation above the bottom of the lake. Land above the water stays visible. Walkable terrain and the game export use the same heights.</div>`;return}
 if(gameSection==='quests'){const q=g.quests.find(o=>o.id===gameQuestSelected);if(!q){P.innerHTML=`<div class="sg-subtitle">QUEST DESIGNER</div><h3>📜 Create real objectives</h3><p>Quests automatically track player actions, reward experience, and level up the player. Choose a quest to edit it.</p><div class="sg-card">Try collecting coins, reaching checkpoints, exploring or defeating enemies.</div>`;return}P.innerHTML=`<div class="sg-subtitle">EDIT QUEST</div><h3>📜 Quest settings</h3><label>Quest title <input data-g-quest="title" value="${esc(q.title)}" maxlength="100"></label><label>Description<textarea data-g-quest="description" rows="3">${esc(q.description||'')}</textarea></label><label>Objective <select data-g-quest="type">${SC_GAME_QUESTS.map(([key,name])=>`<option value="${key}" ${q.type===key?'selected':''}>${name}</option>`).join('')}</select></label><label>Required amount <input type="number" data-g-quest="target" min="1" max="9999" value="${gval(q.target,1)}"></label><label>XP reward <input type="number" data-g-quest="reward" min="0" max="10000" value="${gval(q.reward,100)}"></label><div class="sg-prop-actions"><button data-g-action="cloneQuest">⧉ Duplicate</button><button data-g-action="deleteQuest" class="sg-red">✕ Delete</button></div>`;return}
 if(gameSection==='items'){const item=g.items.find(x=>x.id===gameItemSelected);if(!item){P.innerHTML='<h3>🎒 Item creator</h3><p>Select an item on the left, or click + Create item to define equipment, consumables and materials.</p>';return;}P.innerHTML=`<div class="sg-subtitle">EDIT GAME ITEM</div><h3>${esc(item.icon||'📦')} ${esc(item.name)}</h3><label>Item name<input data-g-item="name" maxlength="60" value="${esc(item.name||'')}"></label><label>Emoji icon<input data-g-item="icon" maxlength="8" value="${esc(item.icon||'📦')}"></label><label>Type<select data-g-item="category">${[['weapon','⚔ Weapon'],['consumable','🍎 Consumable'],['resource','🪵 Resource'],['misc','📦 Miscellaneous']].map(([id,text])=>`<option value="${id}" ${item.category===id?'selected':''}>${text}</option>`).join('')}</select></label><label>Description<textarea data-g-item="description" rows="2">${esc(item.description||'')}</textarea></label><div class="sg-field-grid"><label>Damage / healing<input type="number" data-g-item="power" min="0" max="500" value="${gval(item.power,15)}"></label><label>Attack range (weapons)<input type="number" data-g-item="range" min="1" max="35" value="${gval(item.range,3)}"></label><label>Maximum stack<input type="number" data-g-item="stack" min="1" max="999" value="${gval(item.stack,20)}"></label></div><label class="sg-check"><input type="checkbox" data-g-item="starter" ${item.starter?'checked':''}> Give one when the game starts</label><div class="sg-prop-actions"><button data-g-action="cloneItem">⧉ Duplicate</button><button data-g-action="deleteItem" class="sg-red">✕ Delete</button></div><div class="sg-card">Place a World → Item pickup to let players find this item in your map.</div>`;return}
 if(gameSection==='shop'){const item=g.shop.find(v=>v.id===gameShopSelected);if(!item){P.innerHTML='<div class="sg-subtitle">GAME SHOP</div><h3>🛍 Build your economy</h3><p>Add items, choose prices and effects. Visitors earn coins by exploring and use them for upgrades in the published game.</p>';return}P.innerHTML=`<div class="sg-subtitle">EDIT SHOP ITEM</div><h3>🛍 ${esc(item.name||'Item')}</h3><label>Item name <input data-g-shop="name" value="${esc(item.name||'')}" maxlength="80"></label><label>Effect<select data-g-shop="effect">${SC_GAME_SHOP_EFFECTS.map(([id,label])=>`<option value="${id}" ${item.effect===id?'selected':''}>${label}</option>`).join('')}</select></label><label>Price in coins<input data-g-shop="cost" type="number" min="0" max="100000" value="${gval(item.cost,10)}"></label><label>Effect amount<input data-g-shop="amount" type="number" min="1" max="1000" value="${gval(item.amount,1)}"></label><div class="sg-prop-actions"><button data-g-action="cloneShop">⧉ Duplicate</button><button data-g-action="deleteShop" class="sg-red">✕ Delete</button></div>`;return}
 if(gameSection==='ui'){const b=g.ui.find(o=>o.id===gameUiSelected);if(!b){P.innerHTML=`<div class="sg-subtitle">UI BUTTON DESIGNER</div><h3>🎛 Your game HUD</h3><p>Place your own on-screen buttons for jumping, interacting, opening shops, showing messages and more.</p><div class="sg-card">Custom buttons appear inside your exported or published game, in addition to the default mobile controls.</div>`;return}P.innerHTML=`<div class="sg-subtitle">EDIT UI BUTTON</div><h3>🎛 ${esc(b.label||'New button')}</h3><label>Button text <input data-g-ui="label" value="${esc(b.label||'')}" maxlength="70"></label><label>Icon / emoji <input data-g-ui="icon" value="${esc(b.icon||'')}" maxlength="12"></label><label>Action <select data-g-ui="action">${SC_GAME_ACTIONS.map(([k,n])=>`<option value="${k}" ${b.action===k?'selected':''}>${n}</option>`).join('')}</select></label><label>Custom message or URL <textarea data-g-ui="value" rows="2">${esc(b.value||'')}</textarea></label><div class="sg-field-grid"><label>Left position (%) <input type="number" data-g-ui="x" min="0" max="94" value="${gval(b.x,70)}"></label><label>Top position (%) <input type="number" data-g-ui="y" min="2" max="93" value="${gval(b.y,30)}"></label><label>Text size (px) <input type="number" data-g-ui="size" min="10" max="27" value="${gval(b.size,14)}"></label><label>Corner rounding <input type="number" data-g-ui="radius" min="0" max="40" value="${gval(b.radius,12)}"></label></div><label>Button colour <input type="color" data-g-ui="color" value="${esc(b.color||'#7962e9')}"></label><label class="sg-check"><input type="checkbox" data-g-ui="visible" ${b.visible!==false?'checked':''}> Show button in game</label><div class="sg-prop-actions"><button data-g-action="cloneUi">⧉ Duplicate</button><button data-g-action="deleteUi" class="sg-red">✕ Delete</button></div>`;return}
 if(gameSection==='tools'){P.innerHTML=`<div class="sg-subtitle">WORLD BUILDING TOOLS</div><h3>🧰 Build faster</h3><p>Generate a village, forest, parkour course or lines of editable structures. Select an object in World to duplicate or mirror it.</p><div class="sg-card"><b>Tips</b><br>• Ctrl+D duplicates the selected object.<br>• Delete removes it.<br>• Ctrl+Z undoes your last action.<br>• Generators preserve your existing map.<br>• Each object can still be moved or recoloured.</div>`;return}if(gameSection==='settings'){const s=g.settings;P.innerHTML=`<div class="sg-subtitle">GAMEPLAY RULES</div><h3>⚙ World & player</h3><p>Changes apply to playtest, HTML export, and your public game.</p><label>Sky colour <input data-g-setting="sky" type="color" value="${esc(s.sky||'#9dd0f5')}"></label><label>Ground colour <input data-g-setting="ground" type="color" value="${esc(s.ground||'#75b681')}"></label><label>Character outfit <input data-g-setting="playerColor" type="color" value="${esc(s.playerColor||'#8565eb')}"></label><label>Time of day <select data-g-setting="timeOfDay"><option value="day" ${s.timeOfDay==='day'?'selected':''}>☀ Daytime</option><option value="night" ${s.timeOfDay==='night'?'selected':''}>🌙 Night</option></select></label><div class="sg-field-grid">${[['size','Map size'],['speed','Running speed'],['jump','Jump strength'],['gravity','Gravity'],['maxHealth','Starting health'],['fog','Fog strength'],['ambient','World light'],['coinsForWin','Coins needed to finish']].map(([key,label])=>`<label>${label}<input type="number" data-g-setting="${key}" step="${key==='ambient'?'0.1':'1'}" value="${esc(String(s[key]??0))}"></label>`).join('')}</div><div class="sg-card"><b>Quick world size</b><div class="sg-prop-actions">${[[100,'Small'],[250,'Medium'],[500,'Large'],[1000,'Huge']].map(([v,name])=>`<button type="button" data-g-world-size="${v}">${name} · ${v}</button>`).join('')}</div></div><p class="sg-help"><b>World size:</b> increase Map size up to 1,200 units. Bigger worlds give you more room, but the 65×65 sculpting grid becomes less detailed per metre. For detailed landscapes, keep your main play area around 100–350 units.</p><div class="sg-card">Tip: Open World tools to fill your expanded map with buildings and scenery. Drag the camera farther away using the mouse wheel.</div><label>Finish message <input data-g-setting="winMessage" maxlength="100" value="${esc(s.winMessage||'Level completed!')}"></label><label class="sg-check"><input type="checkbox" data-g-setting="sound" ${s.sound!==false?'checked':''}> Sound effects enabled</label><label class="sg-check"><input type="checkbox" data-g-setting="showHUD" ${s.showHUD!==false?'checked':''}> Show stats & health bar</label><details class="sg-details" open><summary>🌦 Weather & atmosphere</summary><label>Weather<select data-g-setting="weather">${[['clear','☀ Clear'],['rain','🌧 Rain'],['snow','❄ Snow'],['fireflies','✨ Fireflies'],['embers','🔥 Floating embers']].map(([k,v])=>`<option value="${k}" ${s.weather===k?'selected':''}>${v}</option>`).join('')}</select></label><label>Weather intensity (%) <input data-g-setting="weatherIntensity" type="number" min="0" max="100" value="${gval(s.weatherIntensity,35)}"></label><label class="sg-check"><input type="checkbox" data-g-setting="dayCycle" ${s.dayCycle?'checked':''}> Animated day and night cycle</label><label>Day cycle duration (seconds) <input data-g-setting="dayCycleSpeed" type="number" min="30" max="900" value="${gval(s.dayCycleSpeed,100)}"></label></details><details class="sg-details" open><summary>🎮 Player experience</summary><label>Game intro / subtitle <textarea data-g-setting="gameSubtitle" rows="2">${esc(s.gameSubtitle||'')}</textarea></label><label class="sg-check"><input type="checkbox" data-g-setting="gameIntro" ${s.gameIntro!==false?'checked':''}> Show start screen</label><label class="sg-check"><input type="checkbox" data-g-setting="showMiniMap" ${s.showMiniMap!==false?'checked':''}> Show minimap</label><label class="sg-check"><input type="checkbox" data-g-setting="showStamina" ${s.showStamina!==false?'checked':''}> Sprint stamina</label><label class="sg-check"><input type="checkbox" data-g-setting="enableDash" ${s.enableDash!==false?'checked':''}> Allow dash (X key)</label><label class="sg-check"><input type="checkbox" data-g-setting="saveProgress" ${s.saveProgress!==false?'checked':''}> Let players save their local progress</label></details><div class="sg-card">This builder exports **single-player browser games**. Multiplayer servers, Roblox accounts, in-game currency sales and advanced asset imports need separate backend systems.</div>`;return}
 const a=gameSelectedObject();if(!a){P.innerHTML=`<div class="sg-subtitle">SELECT AN OBJECT</div><h3>🌎 Design your world</h3><p>Click an object in the map or pick it from the left to edit its colour, shape and behaviour.</p><div class="sg-card"><b>Quick start</b><p>1. Choose a world preset or add objects.<br>2. Add quests and UI buttons.<br>3. Press <b>Playtest</b> to try it.<br>4. Export as HTML or publish the playable game.</p></div><button class="sg-btn" data-g-action="worldSettings" style="width:100%;margin-top:16px">⚙ Open game settings</button>`;return}
 const name=SC_GAME_OBJECTS.find(x=>x[0]===a.type)?.[1]||a.type;
 P.innerHTML=`<div class="sg-subtitle">PROPERTIES · ${esc(a.type.toUpperCase())}</div><label>Object name<input data-g-prop="label" maxlength="100" value="${esc(a.label||'')}"></label><div class="sg-inspector-quick"><button type="button" data-sc-inspector="focus">◎ Focus</button><button type="button" data-sc-inspector="duplicate">⧉ Copy</button><button type="button" data-sc-inspector="savePrefab">🧩 Save model</button></div><p class="sg-pro-help">Press W/E/R then drag the object. Use Snap for precise placement. Exact values are below.</p><label>Object colour <input type="color" data-g-prop="color" value="${esc(a.color||'#8674f0')}"></label><div class="sg-field-grid">${[['x','X position'],['y','Y height'],['z','Z position'],['sx','Width'],['sy','Height'],['sz','Depth'],['rotation','Rotation °']].map(([k,t])=>`<label>${t}<input type="number" data-g-prop="${k}" step="0.5" value="${gval(a[k])}"></label>`).join('')}</div><details class="sg-details" open><summary>✨ Materials & advanced styling</summary><label>Surface material<select data-g-prop="material">${[['default','Default'],['matte','Matte / clay'],['stone','Rough stone'],['metal','Shiny metal'],['polished','Polished plastic'],['glass','Transparent glass']].map(([id,text])=>`<option value="${id}" ${a.material===id?'selected':''}>${text}</option>`).join('')}</select></label><div class="sg-field-grid"><label>Opacity (%)<input data-g-prop="opacity" type="number" min="5" max="100" value="${gval(a.opacity,100)}"></label><label>Glow intensity<input data-g-prop="glow" type="number" min="0" max="5" step="0.2" value="${gval(a.glow,0)}"></label></div><label class="sg-check"><input data-g-prop="collidable" type="checkbox" ${a.collidable!==false?'checked':''}> Solid / collision enabled</label></details><details class="sg-details" open><summary>⚡ Interaction & behaviour</summary><label>Interaction name <input data-g-prop="label" value="${esc(a.label||'')}" maxlength="100"></label><label>NPC dialogue / text<textarea data-g-prop="message" rows="3">${esc(a.message||'')}</textarea></label><div class="sg-field-grid"><label>Coins rewarded / chest loot<input data-g-prop="reward" type="number" value="${gval(a.reward,10)}"></label><label>Damage (enemy/hazard)<input data-g-prop="damage" type="number" value="${gval(a.damage,20)}"></label><label>Enemy/platform speed<input data-g-prop="speed" type="number" step="0.5" value="${gval(a.speed,2)}"></label></div>${a.type==='enemy'?`<label>Enemy health<input data-g-prop="enemyHealth" type="number" min="1" max="10000" value="${gval(a.enemyHealth,40)}"></label>`:''}${['teleporter','portal'].includes(a.type)?`<label>Teleport destination<select data-g-prop="targetId"><option value="">Nearest checkpoint / spawn</option>${g.objects.filter(x=>x.id!==a.id).map(o=>`<option value="${esc(o.id)}" ${a.targetId===o.id?'selected':''}>${esc(o.label||SC_GAME_OBJECTS.find(t=>t[0]===o.type)?.[1]||o.type)} (${gval(o.x)}, ${gval(o.z)})</option>`).join('')}</select></label>`:''}</details>${gameInteractionSettings(a,g)}<div class="sg-prop-actions"><button data-g-action="duplicate">⧉ Duplicate</button><button data-g-action="delete" class="sg-red">✕ Delete</button></div>`;
}
function gameInteractionSettings(a,g){
 const isItem=a.type==='itemPickup';
 const isBuilding=['building','house','cabin','castle','tower','shop','barn','skyscraper'].includes(a.type);
 const isLoot=['chest','secretChest','supplyCrate','lootBarrel','cabinet','dresser','locker','safe','pantry'].includes(a.type),isDoor=['door','lockedDoor','timedGate','slidingDoor','doubleDoor'].includes(a.type),isControl=['switch','lever','buttonSwitch','pressurePlate','lightSwitch'].includes(a.type),isUsable=['bed','campfire','workbench','well','noticeBoard','sign','billboard','vendingMachine','electricLamp','npc','questGiver'].includes(a.type);
 if(!isLoot&&!isDoor&&!isControl&&!isUsable&&!isBuilding&&!isItem)return '';
 const q=(k,v=0)=>gval(a[k],v);const number=(k,name,min=0,max=9999)=>`<label>${name}<input data-g-prop="${k}" type="number" min="${min}" max="${max}" value="${q(k)}"></label>`;
 const check=(k,name,checked=a[k]===true)=>`<label class="sg-check"><input data-g-prop="${k}" type="checkbox" ${checked?'checked':''}> ${name}</label>`;
 let content='';
 if(isItem)content='<label>Item given when collected<select data-g-prop="itemId"><option value="">Choose an item</option>'+g.items.map(v=>`<option value="${esc(v.id)}" ${a.itemId===v.id?'selected':''}>${esc(v.icon||'📦')} ${esc(v.name)}</option>`).join('')+'</select></label>'+number('itemQuantity','Quantity',1,100)+check('repeatable','Can respawn after 30 seconds',a.repeatable===true);
 if(isBuilding){content='<p class="sg-help">Walk inside your building. Its walls, roof and doorway have real collisions; the entrance opens with E. Most buildings come with working furniture, storage or shops. Taller buildings have rooftop lifts.</p>'+check('enterable','Walkable interior (uncheck for a solid decorative block)',a.enterable!==false)+check('locked','Lock the main entrance',a.locked===true)+number('requiredKeys','Entrance keys needed',0,99)+check('consumeKeys','Consume keys when unlocking',a.consumeKeys!==false)+number('closeDelay','Automatically close front door after seconds (0 = off)',0,120);}

 if(isLoot){content='<label>Optional inventory item inside<select data-g-prop="itemId"><option value="">No extra item</option>'+g.items.map(v=>`<option value="${esc(v.id)}" ${a.itemId===v.id?'selected':''}>${esc(v.icon||'📦')} ${esc(v.name)}</option>`).join('')+'</select></label>'+number('itemQuantity','Item quantity',1,100);content+='<p class="sg-help">Walk up and press E / USE to open. Containers stay in the world with an animated lid or door.</p>'+number('rewardGems','💎 Gems inside')+number('rewardKeys','🗝 Keys inside')+number('rewardXp','⭐ XP inside')+number('healAmount','❤️ Health inside')+check('locked','Require a key',a.locked===true||['secretChest','safe'].includes(a.type))+number('requiredKeys','Keys needed',0,99)+check('consumeKeys','Use up keys when opening',a.consumeKeys!==false)+check('repeatable','Allow opening again after 30 seconds');}
 if(isDoor){content='<p class="sg-help">Doors visibly swing or slide when opened. Players can close them again, or use a linked switch.</p>'+check('locked','Require a key',a.locked===true||a.type==='lockedDoor')+number('requiredKeys','Keys to unlock',0,99)+check('consumeKeys','Use keys when unlocking',a.consumeKeys!==false)+number('closeDelay','Auto-close after seconds (0 = stay open)',0,120);}
 if(isControl){const destinations=g.objects.filter(o=>o.id!==a.id&&(['door','lockedDoor','timedGate','slidingDoor','doubleDoor','building','house','cabin','castle','tower','shop','barn','skyscraper','electricLamp'].includes(o.type)));content='<p class="sg-help">Link this control to one door or light. Without a link, it operates the nearest one.</p><label>Linked door / light<select data-g-prop="targetId"><option value="">Auto — closest nearby object</option>'+destinations.map(o=>`<option value="${esc(o.id)}" ${a.targetId===o.id?'selected':''}>${esc(o.label||o.type)} · ${Math.round(gval(o.x))}, ${Math.round(gval(o.z))}</option>`).join('')+'</select></label>'+number('closeDelay','Door closing delay (seconds)',0,120);}
 if(isUsable){content='<p class="sg-help">The player can use this object with E. Set a friendly name and optional dialogue in the fields above.</p>';if(['bed','campfire','well'].includes(a.type))content+=number('healAmount','Health restored when used (0 = default)',0,500);}
 return `<details class="sg-details" open><summary>🧩 Working interaction settings</summary>${content}</details>`;
}
function gamePaletteRender(){const holder=$('gamePalette');if(!holder)return;const query=gameFilter.trim().toLowerCase();holder.innerHTML=SC_GAME_CATEGORIES.map(([category,items])=>{const filtered=items.filter(([id,label])=>label.toLowerCase().includes(query)||id.toLowerCase().includes(query));return filtered.length?`<div class="sg-palette-category"><div class="sg-palette-title">${category}</div><div class="sg-palette-items">${filtered.map(([id,label])=>`<button type="button" data-g-add="${id}" title="Add ${esc(label)} to the scene">${esc(label)}</button>`).join('')}</div></div>`:''}).join('')||'<p>No matching objects. Try another search.</p>'}
function gameObjectList(){sgDisplayStatus();const holder=$('gameObjects');if(!holder||!isGame())return;holder.innerHTML=project.game.objects.map(o=>`<button type="button" class="sg-layer ${gameSelected===o.id?'active':''}" data-g-select="${esc(o.id)}"><span>${esc(o.label||SC_GAME_OBJECTS.find(x=>x[0]===o.type)?.[1]||o.type)}</span><small>${Math.round(o.x)}, ${Math.round(o.z)}</small></button>`).join('');$('gameCount').textContent=project.game.objects.length+' objects'}
function gameItemsList(){const box=$('gameItemsList');if(!box||!isGame())return;box.innerHTML=(project.game.items||[]).map(v=>`<button type="button" class="sg-layer ${v.id===gameItemSelected?'active':''}" data-g-item-select="${esc(v.id)}"><span>${esc(v.icon||'📦')} ${esc(v.name||'Item')}</span><small>${esc(v.category||'misc')}</small></button>`).join('')||'<p class="sg-help">Add your first item above.</p>'}
function gameShopList(){const holder=$('gameShopList');if(!holder||!isGame())return;holder.innerHTML=(project.game.shop||[]).map(v=>`<button type="button" class="sg-layer ${v.id===gameShopSelected?'active':''}" data-g-shop-select="${esc(v.id)}"><span>🛍 ${esc(v.name||'Shop item')}</span><small>${gval(v.cost,10)} 🪙</small></button>`).join('')||'<p class="sg-help">Your shop is empty. Add an item above.</p>'}
function gameQuestList(){const holder=$('gameQuests');if(!holder||!isGame())return;holder.innerHTML=project.game.quests.map(q=>`<button class="sg-layer ${q.id===gameQuestSelected?'active':''}" data-g-quest-select="${esc(q.id)}"><span>📜 ${esc(q.title||'Unnamed quest')}</span><small>${esc(q.type)} × ${gval(q.target,1)}</small></button>`).join('')||'<p class="sg-help">No quests yet. Add one below.</p>'}
function gameUiList(){const holder=$('gameUIList');if(!holder||!isGame())return;holder.innerHTML=project.game.ui.map(b=>`<button class="sg-layer ${b.id===gameUiSelected?'active':''}" data-g-ui-select="${esc(b.id)}"><span>${esc(b.icon||'🎛')} ${esc(b.label||'Button')}</span><small>${esc(b.action)}</small></button>`).join('')||'<p class="sg-help">Add a button to build your own game interface.</p>'}

// --- Studio PRO: explorer, reusable models, bulk actions, checks. ---
let sgMulti=new Set(),sgExplorerFilter='',sgTransformMode='select',sgClipboard=null;
function sgSelectedIds(){if(!isGame())return [];const ids=new Set(project.game.objects.map(x=>x.id));return [...sgMulti].filter(id=>ids.has(id));}
function sgEnsureExtras(){if(!isGame())return;const g=project.game;if(!Array.isArray(g.prefabs))g.prefabs=[];if(!Array.isArray(g.folders))g.folders=[];}
function sgObjectName(o){return o.label||SC_GAME_OBJECTS.find(x=>x[0]===o.type)?.[1]||o.type}
function sgDisplayStatus(){const n=sgSelectedIds().length;const st=$('sgProStatus');if(st)st.textContent=n>1?n+' objects selected':gameSelectedObject()?sgObjectName(gameSelectedObject()):'Select an object · Q/W/E/R';document.querySelectorAll('[data-sc-transform]').forEach(b=>b.classList.toggle('active',b.dataset.scTransform===sgTransformMode));}
function sgSendView(type='select',id=gameSelected){const frame=$('gameFrame');if(!frame?.contentWindow)return;frame.contentWindow.postMessage({sitecraftScene:true,type,id,selection:sgSelectedIds(),mode:sgTransformMode,snap:$('sgSnapCheck')?.checked!==false,step:gval($('sgSnapStep')?.value,1),flags:project.game.objects.map(o=>({id:o.id,hidden:o.editorHidden===true,locked:o.editorLocked===true}))},'*');sgDisplayStatus()}
function sgExploreRender(){if(!isGame())return;sgEnsureExtras();const holder=$('sgSceneTree');if(!holder)return;const objects=project.game.objects;const active=new Set(objects.map(o=>o.id));sgMulti=new Set([...sgMulti].filter(id=>active.has(id)));const query=sgExplorerFilter.trim().toLowerCase();const groups=new Map();for(const obj of objects){const folder=String(obj.folder||'World');if(!groups.has(folder))groups.set(folder,[]);if(!query||[sgObjectName(obj),obj.type,folder].join(' ').toLowerCase().includes(query))groups.get(folder).push(obj)};
 holder.innerHTML=[...groups].filter(([,v])=>v.length).sort((a,b)=>a[0].localeCompare(b[0])).map(([folder,items])=>`<div class="sg-tree-folder">📁 ${esc(folder)} <small>${items.length} parts</small></div>`+items.map(o=>`<div class="sg-tree-item ${gameSelected===o.id?'active':''}" data-sc-id="${esc(o.id)}"><input type="checkbox" data-sc-multi="${esc(o.id)}" ${sgMulti.has(o.id)?'checked':''} aria-label="Select ${esc(sgObjectName(o))}"><button type="button" class="sg-tree-name" data-sc-tree-select="${esc(o.id)}" title="${esc(o.type)} · ${Math.round(gval(o.x))}, ${Math.round(gval(o.z))}">${o.editorHidden?'◌ ':''}${esc(sgObjectName(o))}</button><button type="button" class="sg-tree-icon ${o.editorHidden?'off':''}" data-sc-eye="${esc(o.id)}" title="Show/hide in editor">${o.editorHidden?'◌':'◉'}</button><button type="button" class="sg-tree-icon ${o.editorLocked?'off':''}" data-sc-lock="${esc(o.id)}" title="Lock/unlock editing">${o.editorLocked?'🔒':'🔓'}</button></div>`).join('')).join('')||'<div class="sg-pro-empty">No matching objects. Clear the search to see your scene.</div>';
 const count=$('sgExplorerCount');if(count)count.textContent=sgSelectedIds().length+' selected · '+objects.length+' total';sgDisplayStatus();}
function sgSelect(id,add=false){if(!isGame())return;if(id&&!project.game.objects.some(x=>x.id===id))return;if(!add)sgMulti.clear();if(id){gameSelected=id;if(add&&sgMulti.has(id))sgMulti.delete(id);else sgMulti.add(id)}else gameSelected=null;gameObjectList();sgExploreRender();gameStylePanel();sgSendView();}
function sgPrefabRender(){if(!isGame())return;sgEnsureExtras();$('sgPrefabList').innerHTML=project.game.prefabs.map((p,i)=>`<div class="sg-pro-card"><b>🧩 ${esc(p.name||'Model '+(i+1))}</b><small>${(p.parts||[]).length} editable parts</small><div class="sg-pro-buttons"><button data-sc-prefab-add="${esc(p.id)}">＋ Place model</button><button data-sc-prefab-remove="${esc(p.id)}">✕ Delete model</button></div></div>`).join('')||'<div class="sg-pro-empty">No models saved yet. Select a group of objects in Explorer and choose Save selection as model.</div>'}
function sgSavePrefab(){if(!isGame())return;sgEnsureExtras();let ids=sgSelectedIds();if(!ids.length&&gameSelectedObject())ids=[gameSelected];if(!ids.length){toast('Select at least one world object in Explorer first.');return}const objects=ids.map(id=>project.game.objects.find(o=>o.id===id)).filter(Boolean);const title=prompt('Name this reusable model:',objects.length===1?sgObjectName(objects[0]):'My custom model');if(title===null)return;const x=objects.reduce((v,o)=>v+gval(o.x),0)/objects.length,z=objects.reduce((v,o)=>v+gval(o.z),0)/objects.length;const item={id:uid(),name:title.trim().slice(0,75)||'Custom model',parts:objects.map(o=>({...deep(o),x:gval(o.x)-x,z:gval(o.z)-z,editorHidden:false,editorLocked:false}))};checkpoint();project.game.prefabs.push(item);gameChanged(false);sgPrefabRender();toast('Saved model: '+item.name)}
function sgPlacePrefab(id){sgEnsureExtras();const pf=project.game.prefabs.find(p=>p.id===id);if(!pf)return;const n=pf.parts?.length||0;if(!n||project.game.objects.length+n>600){toast('Not enough room for this model: maximum 600 objects.');return}checkpoint();const all=new Map(),ox=5+(project.game.objects.length%7)*7,oz=5+(project.game.objects.length%9)*4;const clones=pf.parts.map(o=>{const c={...deep(o),id:uid(),x:gval(o.x)+ox,z:gval(o.z)+oz};all.set(o.id,c.id);return c});for(const c of clones){if(c.targetId&&all.has(c.targetId))c.targetId=all.get(c.targetId);project.game.objects.push(c)}sgMulti=new Set(clones.map(o=>o.id));gameSelected=clones[0]?.id||null;gameSection='explorer';gameChanged();toast('Placed '+n+' editable parts from '+pf.name)}
function sgBulkAction(mode){if(!isGame())return;let ids=sgSelectedIds();if(!ids.length&&gameSelectedObject())ids=[gameSelected];if(!ids.length){toast('Select one or more objects first.');return}const list=ids.map(id=>project.game.objects.find(o=>o.id===id)).filter(Boolean);
 if(mode==='model'){sgSavePrefab();return}
 if(mode==='focus'){sgSendView('focus',gameSelected||ids[0]);return}
 if(mode==='copy'){sgClipboard=deep(list);toast('Copied '+list.length+' object'+(list.length===1?'':'s'));return}
 if(mode==='paste'){if(!sgClipboard?.length){toast('Copy an object or group first.');return}if(project.game.objects.length+sgClipboard.length>600){toast('This scene has reached its 600-object limit.');return}checkpoint();const map=new Map();const clones=sgClipboard.map(o=>{const copy=deep(o);const prev=copy.id;copy.id=uid();map.set(prev,copy.id);copy.x=gval(copy.x)+3;copy.z=gval(copy.z)+3;return copy});for(const c of clones)if(map.has(c.targetId))c.targetId=map.get(c.targetId);project.game.objects.push(...clones);sgMulti=new Set(clones.map(o=>o.id));gameSelected=clones[0]?.id;gameChanged();return}
 if(mode==='duplicate'){sgBulkAction('copy');sgBulkAction('paste');return}
 if(mode==='delete'){if(!confirm('Delete '+list.length+' selected object(s)?'))return;checkpoint();const drop=new Set(ids);project.game.objects=project.game.objects.filter(o=>!drop.has(o.id));sgMulti.clear();gameSelected=null;gameChanged();return}
 if(mode==='folder'){const name=prompt('Folder name for '+list.length+' object(s):',list[0].folder||'Buildings');if(name===null)return;checkpoint();for(const o of list)o.folder=name.trim().slice(0,60)||'World';gameChanged(false);sgExploreRender();return}
 if(mode==='visible'||mode==='locked'){checkpoint();const key=mode==='visible'?'editorHidden':'editorLocked';const val=!list.every(o=>o[key]);for(const o of list)o[key]=val;gameChanged(false);sgExploreRender();sgSendView();return}
 if(['x','y','z'].includes(mode)){const delta=Number(prompt('Move selection by how many units on '+mode.toUpperCase()+'?', '1'));if(!Number.isFinite(delta)||!delta)return;checkpoint();for(const o of list)o[mode]=gval(o[mode])+delta;gameChanged();return}
}
function sgAuditRender(){if(!isGame())return;const holder=$('sgAuditResults');if(!holder)return;const G=project.game,objects=G.objects||[],ids=new Set(objects.map(o=>o.id)),issues=[];if(!objects.some(o=>o.type==='spawn'))issues.push(['warning','No spawn point.','Place a Spawn object for reliable starting positions.']);const half=gval(G.settings?.size,100)/2;for(const o of objects){const name=sgObjectName(o);if(!Number.isFinite(Number(o.x))||!Number.isFinite(Number(o.z)))issues.push(['error',name+' has invalid coordinates.','Set a valid X/Z position.']);if(Math.abs(gval(o.x))>half||Math.abs(gval(o.z))>half)issues.push(['warning',name+' is outside the map.','Move it closer to the centre or enlarge the world.']);if(o.targetId&&!ids.has(o.targetId))issues.push(['warning',name+' has a missing target.','Open its Properties and select a valid linked object.']);if(gval(o.sx,1)<=0||gval(o.sy,1)<=0||gval(o.sz,1)<=0)issues.push(['error',name+' has non-positive dimensions.','Width, height and depth must be greater than zero.'])}if(ids.size!==objects.length)issues.push(['error','Duplicate object IDs','Duplicate IDs may cause unexpected interactions.']);if(objects.length>=520)issues.push(['warning','Scene is near the 600-object cap.','Use smaller worlds or remove unnecessary decorations.']);if(gval(G.settings?.size,100)>400)issues.push(['note','Very large terrain','The current 65×65 terrain mesh has reduced detail at this size.']);if(!issues.length)issues.push(['good','Your game passes the checks!','No common scene mistakes detected.']);const errors=issues.filter(x=>x[0]==='error').length;holder.innerHTML=`<div class="sg-pro-card"><b>${errors?'❗ '+errors+' errors detected':'✅ Build checks complete'}</b><small>${objects.length} objects · ${issues.length} findings · ${gval(G.settings?.size,100)}-unit map</small></div>`+issues.slice(0,85).map(([level,title,desc])=>`<div class="sg-pro-card"><b>${level==='error'?'🛑':level==='warning'?'⚠️':level==='good'?'✅':'ℹ️'} ${esc(title)}</b><small>${esc(desc)}</small></div>`).join('');}
function sgTransformFromInspector(action){const obj=gameSelectedObject();if(!obj)return;if(action==='focus'){sgBulkAction('focus');return}if(action==='duplicate'){sgBulkAction('duplicate');return}if(action==='savePrefab'){sgBulkAction('model');return}}

function gameSectionRender(){document.querySelectorAll('[data-g-section]').forEach(b=>b.classList.toggle('active',b.dataset.gSection===gameSection));['world','explorer','models','check','terrain','items','quests','shop','ui','tools','settings'].forEach(s=>{const e=$('gameSection-'+s);if(e)e.hidden=gameSection!==s});if(gameSection==='world'){gamePaletteRender();gameObjectList()}if(gameSection==='explorer')sgExploreRender();if(gameSection==='models')sgPrefabRender();if(gameSection==='check')sgAuditRender();if(gameSection==='items')gameItemsList();if(gameSection==='quests')gameQuestList();if(gameSection==='shop')gameShopList();if(gameSection==='ui')gameUiList();if(gameSection==='tools')gameToolRender();gameStylePanel();terrainSendTool();studioUiSync()}
let sgLastViewportGame=null;
function sgCanLivePatch(before,after){if(!before||!after||before.objects?.length!==after.objects?.length)return false;
 const getFixed=(g)=>{const c=deep(g);delete c.objects;return JSON.stringify(c)};
 if(getFixed(before)!==getFixed(after))return false;
 const allowed=new Set(['x','y','z','rotation','label','folder','editorHidden','editorLocked']);
 return before.objects.every((o,i)=>{const n=after.objects[i];if(o.id!==n.id||o.type!==n.type)return false;return Object.keys({...o,...n}).every(k=>allowed.has(k)||JSON.stringify(o[k])===JSON.stringify(n[k]));});}
function gameFrameRefresh(){if(!isGame()||!$('gameStudio').classList.contains('show'))return;const frame=$('gameFrame'),now=deep(project.game);
 if(sgCanLivePatch(sgLastViewportGame,now)&&frame.contentWindow){const changed=now.objects.filter((o,i)=>JSON.stringify(o)!==JSON.stringify(sgLastViewportGame.objects[i]));if(changed.length){frame.contentWindow.postMessage({sitecraftScene:true,type:'patch',objects:changed},'*');}sgLastViewportGame=now;sgSendView();return;}
 sgLastViewportGame=now;frame.srcdoc=buildGameHtml(project,true);}

function showGameEditor(){gameEnsure();sgEnsureExtras();$('gameStudio').classList.add('show');$('gameTitleInput').value=project.name;gameSectionRender();const frameState=JSON.stringify(project.game);if(gameCurrentFrame!==frameState){gameCurrentFrame=frameState;gameFrameRefresh()}}
function hideGameEditor(){$('gameStudio').classList.remove('show');gameCurrentFrame='';sgLastViewportGame=null;gameSelected=null;sgMulti.clear()}
function gameChanged(refresh=true){if(!refresh){gameCurrentFrame=JSON.stringify(project.game);commit(false)}else commit()}
