function addGameObject(type){if(!isGame()||!SC_GAME_OBJECTS.some(x=>x[0]===type))return;if(project.game.objects.length>=600){toast('For performance, each map supports up to 600 objects. Remove objects or simplify the world first.');return}checkpoint();const c=project.game.objects.length,d=GAME_DIMS[type]||GAME_DIMS.block;const item=gameObject(type,((c*7)%25)-12,0,((c*11)%31)-15,...d);if(type==='spawn')project.game.objects=project.game.objects.filter(x=>x.type!=='spawn');project.game.objects.push(item);gameSelected=item.id;gameSection='world';gameChanged();toast((SC_GAME_OBJECTS.find(x=>x[0]===type)?.[1]||type)+' added')}
function gameToolRender(){const select=$('gameToolType');if(!select||!isGame())return;const previous=select.value||'tree';select.innerHTML=SC_GAME_CATEGORIES.map(([n,items])=>`<optgroup label="${esc(n)}">${items.map(([t,l])=>`<option value="${esc(t)}">${esc(l)}</option>`).join('')}</optgroup>`).join('');select.value=SC_GAME_OBJECTS.some(i=>i[0]===previous)?previous:'tree'}
function gameBulkAdd(list,label='Objects'){if(!list.length)return;const available=Math.max(0,600-project.game.objects.length);if(!available){toast('World object limit reached.');return}checkpoint();const added=list.slice(0,available);project.game.objects.push(...added);gameSelected=added.at(-1).id;gameSection='world';gameChanged();toast(`${added.length} ${label} added — edit each object in World. Use Undo to revert.`)}
function gameBuildTool(action){if(!isGame())return;const g=project.game,a=gameSelectedObject(),type=$('gameToolType').value||'tree',n=clamp(Math.round(gval($('gameToolCount').value,8)),2,75),space=clamp(gval($('gameToolSpacing').value,5),1,25),base=GAME_DIMS[type]||GAME_DIMS.block;const at=(t,x,z,rot=0)=>gameObject(t,x,0,z,...(GAME_DIMS[t]||GAME_DIMS.block),rot);
 let items=[];
 if(['row','circle','scatter','grid'].includes(action)){
  for(let i=0;i<n;i++){let x,z;if(action==='row'){x=(i-(n-1)/2)*space;z=0}else if(action==='circle'){x=Math.cos(i/n*Math.PI*2)*space*n/5;z=Math.sin(i/n*Math.PI*2)*space*n/5}else if(action==='grid'){const side=Math.ceil(Math.sqrt(n));x=(i%side-(side-1)/2)*space;z=(Math.floor(i/side)-(side-1)/2)*space}else{x=(Math.random()-.5)*space*n*.8;z=(Math.random()-.5)*space*n*.8}items.push(at(type,x,z))}}
 if(action==='duplicate5'&&a){for(let i=1;i<=5;i++)items.push({...a,id:uid(),x:gval(a.x)+i*Math.max(2,space),z:gval(a.z)})}
 if(action==='mirror'&&a)items.push({...a,id:uid(),x:-gval(a.x),z:-gval(a.z),rotation:(360-gval(a.rotation))%360});
 if(action==='randomColors'){if(!confirm('Randomise colours of the current scene?'))return;checkpoint();const palette=['#53c4dc','#81ba7e','#e6b86b','#c987d5','#da8585','#7f93c5'];g.objects.forEach(o=>o.color=palette[Math.floor(Math.random()*palette.length)]);gameChanged();return}
 if(action==='clearDecorations'){if(!confirm('Remove purely decorative objects? Gameplay objects, spawn and goals will be kept.'))return;checkpoint();const protectedTypes=new Set(['spawn','goal','checkpoint','enemy','npc','questGiver','shopKeeper','coin','gem','star','key','lockedDoor','savePoint','messageZone','questZone','teleporter','portal','chest','secretChest','supplyCrate','lootBarrel','cabinet','dresser','locker','safe','pantry','slidingDoor','doubleDoor','lever','buttonSwitch','pressurePlate','lightSwitch','electricLamp','vendingMachine','workbench','noticeBoard','well','spikes','hazard','rotatingHazard','switch','door','timedGate','health','xpPickup','rewardPad','finishBanner']);g.objects=g.objects.filter(o=>protectedTypes.has(o.type));gameSelected=null;gameChanged();return}
 if(items.length)gameBulkAdd(items,action==='duplicate5'?'copies':'objects');else toast('Select an object in World first.');
}
function gameGenerator(kind){if(!isGame())return;const add=(t,x,z,rot=0)=>gameObject(t,x,0,z,...(GAME_DIMS[t]||GAME_DIMS.block),rot);let items=[];
 const circle=(type,n,r)=>{for(let i=0;i<n;i++)items.push(add(type,Math.cos(i*2*Math.PI/n)*r,Math.sin(i*2*Math.PI/n)*r))};
 const scatter=(types,n,r)=>{for(let i=0;i<n;i++)items.push(add(types[i%types.length],(Math.random()-.5)*r*2,(Math.random()-.5)*r*2))};
 switch(kind){
 case'forest':scatter(['tree','pine','bush','rock','flower','giantMushroom','treeStump'],42,35);items.push(add('chest',-14,-12),add('npc',3,7));break;
 case'village':for(let i=0;i<12;i++){const x=(i%4-1.5)*13,z=(Math.floor(i/4)-1)*18;items.push(add(i%3===0?'shop':i%3===1?'house':'cabin',x,z))}items.push(add('fountain',0,0),add('marketStall',5,20));circle('lamp',8,29);break;
 case'parkour':for(let i=0;i<14;i++){const o=add(i%5===0?'movingPlatform':'platform',Math.sin(i*.7)*9,18-i*7);o.y=i*.72;o.sy=1;o.sx=5;o.sz=5;items.push(o);if(i%3===0){const cp=add('checkpoint',o.x,o.z);cp.y=o.y+1;items.push(cp)}}items.push(add('goal',0,-82));break;
 case'city':for(let i=0;i<16;i++){const x=(i%4-1.5)*18,z=(Math.floor(i/4)-1.5)*19;items.push(add(i%3===0?'skyscraper':i%3===1?'building':'shop',x,z))}for(let i=-1;i<=1;i++){const r=add('road',i*18,0);r.sz=85;items.push(r)}circle('lamp',10,34);break;
 case'garden':circle('flower',16,17);circle('bush',10,12);items.push(add('gazebo',0,0),add('fountain',0,-8),add('bench',-12,0),add('bench',12,0));break;
 case'loot':for(let i=0;i<25;i++){const v=add(i%5===0?'gem':'coin',Math.sin(i*.61)*14,19-i*2);v.y=1;items.push(v)}items.push(add('chest',0,-34),add('goal',0,-39));break;
 case'arena':for(const [x,z,sx,sz] of [[-28,0,2,55],[28,0,2,55],[0,-28,55,2],[0,28,55,2]]){const wall=add('wall',x,z);wall.sx=sx;wall.sz=sz;items.push(wall)}circle('enemy',12,17);items.push(add('health',0,0),add('savePoint',0,19));break;
 case'interiors':{const floor=add('floorTile',0,-2);floor.sx=38;floor.sz=36;floor.sy=.2;items.push(floor);for(const [x,z,sx,sz] of [[-18,-2,1,36],[18,-2,1,36],[0,-20,37,1],[-11,16,15,1],[11,16,15,1]]){const wall=add('wall',x,z);wall.sx=sx;wall.sz=sz;wall.sy=6;items.push(wall)}const door=add('lockedDoor',0,16);door.requiredKeys=1;door.label='Front door';items.push(door);const key=add('key',-10,21);key.label='Front door key';items.push(key);const chest=add('chest',-8,-10);chest.reward=25;chest.rewardGems=2;items.push(chest);const safe=add('safe',12,-10);safe.reward=70;safe.requiredKeys=1;items.push(safe);const lever=add('lever',-6,4);lever.targetId=door.id;items.push(lever);items.push(add('bed',7,9),add('workbench',-12,-5),add('cabinet',13,6),add('vendingMachine',-13,11),add('electricLamp',6,-2),add('lightSwitch',8,-1),add('noticeBoard',0,-15),add('well',24,12));break;}
  case'farm':for(let i=0;i<20;i++)items.push(add(i%3?'wheat':'hayBale',(i%5-2)*7,(Math.floor(i/5)-2)*7));items.push(add('barn',26,5),add('windmill',-26,5),add('fence',0,-21));break;
 default:return;
 }
 gameBulkAdd(items,kind+' scenery');}
function gameNewTemplate(t){sgMulti.clear();sgLastViewportGame=null;if(!confirm('Replace the current map, quests and UI with the '+t+' starter template? Export a backup first if you need the old map.'))return;checkpoint();project.game=newGameProject(t).game;gameSelected=null;gameQuestSelected=null;gameUiSelected=null;gameSection='world';gameChanged()}
function gameAction(action){const a=gameSelectedObject(),g=project.game;switch(action){case'delete':if(a){checkpoint();g.objects=g.objects.filter(x=>x.id!==a.id);gameSelected=null;gameChanged()}break;case'duplicate':if(a){checkpoint();const b={...a,id:uid(),x:gval(a.x)+4,z:gval(a.z)+4};g.objects.push(b);gameSelected=b.id;gameChanged()}break;case'deleteItem':{checkpoint();g.items=g.items.filter(v=>v.id!==gameItemSelected);gameItemSelected=null;gameChanged();break}case'cloneItem':{const v=g.items.find(x=>x.id===gameItemSelected);if(v){checkpoint();const b={...v,id:uid(),name:v.name+' copy'};g.items.push(b);gameItemSelected=b.id;gameChanged()}break}case'deleteShop':{checkpoint();g.shop=g.shop.filter(v=>v.id!==gameShopSelected);gameShopSelected=null;gameChanged();break}case'cloneShop':{const v=g.shop.find(v=>v.id===gameShopSelected);if(v){checkpoint();const b={...v,id:uid(),name:v.name+' copy'};g.shop.push(b);gameShopSelected=b.id;gameChanged()}break}case'deleteQuest':{checkpoint();g.quests=g.quests.filter(q=>q.id!==gameQuestSelected);gameQuestSelected=null;gameChanged();break}case'cloneQuest':{const q=g.quests.find(x=>x.id===gameQuestSelected);if(q){checkpoint();const b={...q,id:uid(),title:q.title+' copy'};g.quests.push(b);gameQuestSelected=b.id;gameChanged()}break}case'deleteUi':{checkpoint();g.ui=g.ui.filter(x=>x.id!==gameUiSelected);gameUiSelected=null;gameChanged();break}case'cloneUi':{const b=g.ui.find(x=>x.id===gameUiSelected);if(b){checkpoint();const n={...b,id:uid(),y:Math.min(90,gval(b.y)+9)};g.ui.push(n);gameUiSelected=n.id;gameChanged()}break}case'worldSettings':gameSection='settings';gameSectionRender();break;}}
function gamePreview(){const frame=$('previewFrame');const title=$('previewModal').querySelector('.modal-head h2');if(title)title.textContent='Playtest: '+project.name;frame.removeAttribute('srcdoc');frame.srcdoc=buildGameHtml(project,false);openModal('previewModal')}
