document.addEventListener('keydown',e=>{if(!isGame()||!$('gameStudio').classList.contains('show')||gameSection!=='terrain'||['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName)||e.ctrlKey||e.altKey||e.metaKey)return;const tools=['raise','lower','smooth','flatten','paint','water','sample','none'];const v=Number(e.key);if(v>=1&&v<=8){studioChooseTool(tools[v-1]);e.preventDefault();return}if(e.key==='['||e.key===']'){terrainRadius=Math.max(2,Math.min(30,terrainRadius+(e.key==='['?-2:2)));studioUiSync();terrainSendTool();e.preventDefault()}});
