 function studioTerrainChange(a){const v=gval(a.value);if(a.dataset.terrainInput==='radius')terrainRadius=Math.max(2,Math.min(200,v));else if(a.dataset.terrainInput==='strength')terrainStrength=Math.max(.2,Math.min(8,v));else terrainFlatten=Math.max(-25,Math.min(45,v));studioUiSync();terrainSendTool()}
