 $('gameProps').addEventListener('change',e=>{const v=e.target;if(v.matches('[data-g-setting]')){checkpoint();const k=v.dataset.gSetting;project.game.settings[k]=v.type==='checkbox'?v.checked:v.type==='number'?(k==='size'?Math.max(30,Math.min(1200,gval(v.value,100))):gval(v.value)):v.value;if(k==='size')terrainRadius=Math.max(terrainRadius,Math.ceil(project.game.settings.size/(TERRAIN_RES-1)*1.3));gameChanged()}
 if(v.matches('[data-g-prop]')){const o=gameSelectedObject();if(!o)return;checkpoint();o[v.dataset.gProp]=v.type==='checkbox'?v.checked:v.type==='number'?gval(v.value):v.value;gameChanged()}
 if(v.matches('[data-g-item]')){const item=project.game.items.find(t=>t.id===gameItemSelected);if(!item)return;checkpoint();item[v.dataset.gItem]=v.type==='checkbox'?v.checked:v.type==='number'?gval(v.value):v.value;gameChanged()}
 if(v.matches('[data-g-shop]')){const item=project.game.shop.find(t=>t.id===gameShopSelected);if(!item)return;checkpoint();item[v.dataset.gShop]=v.type==='number'?gval(v.value):v.value;gameChanged()}
 if(v.matches('[data-g-quest]')){const q=project.game.quests.find(q=>q.id===gameQuestSelected);if(!q)return;checkpoint();q[v.dataset.gQuest]=v.type==='number'?gval(v.value):v.value;gameChanged()}
 if(v.matches('[data-g-ui]')){const b=project.game.ui.find(b=>b.id===gameUiSelected);if(!b)return;checkpoint();b[v.dataset.gUi]=v.type==='checkbox'?v.checked:v.type==='number'?gval(v.value):v.value;gameChanged()}});
 $('gameProps').addEventListener('click',e=>{const b=e.target.closest('[data-g-world-size]');if(!b)return;checkpoint();project.game.settings.size=Number(b.dataset.gWorldSize);terrainRadius=Math.max(terrainRadius,Math.ceil(project.game.settings.size/(TERRAIN_RES-1)*1.3));gameChanged();toast('World expanded to '+project.game.settings.size+' units. Zoom out or choose Top view to see the whole map.')});
 $('gameProps').addEventListener('click',e=>{const b=e.target.closest('[data-g-action]');if(b)gameAction(b.dataset.gAction)});
